import React from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { ChevronLeftIcon, ChevronUpIcon, ChevronDownIcon } from '@heroicons/react/24/outline';

import Markdown from '../components/common/Markdown';
import CircularImage from '../components/common/CircularImage';
import LoadingSpinner from '../components/common/LoadingSpinner';
import ErrorDisplay from '../components/common/ErrorDisplay';
import FilmList from '../components/films/FilmList';
import InterviewItem from '../components/profile/InterviewItem';
import ProfileStatsSection from '../components/profile/ProfileStatsSection';
import ControversialFilmItem from '../components/profile/ControversialFilmItem';
import PageLayout from '../components/layout/PageLayout';
import ProfileBlurbItem from '../components/profile/ProfileBlurbItem';
import AccentCard from '../components/common/AccentCard';
import Button from '../components/common/Button';
import HeroBanner from '../components/common/HeroBanner';
import ProfileTrophyGallery from '../components/profile/ProfileTrophyGallery';
import ProfileListsSection from '../components/profile/ProfileListsSection';
import ProfileWatchedSection from '../components/profile/ProfileWatchedSection';
import ProfileEditor from '../components/profile/ProfileEditor';
import { useClubAuth } from '../auth/GoogleAuth';

import { useMemberProfile } from '../hooks/useMemberProfile';
import { useProfileData } from '../hooks/useProfileData';

const ProfilePage: React.FC = () => {
    const { memberName } = useParams<{ memberName: string }>();
    const navigate = useNavigate();

    const {
        member,
        selectedFilms,
        topRatedFilms,
        mostControversialFilms,
        currentUserStats,
        rankings,
        reviewBlurbs,
        lists,
        allFilms,
        loading,
        error,
        isInterviewExpanded,
        toggleInterviewExpanded,
        isBlurbsSectionExpanded,
        toggleBlurbsSectionExpanded,
    } = useProfileData(memberName);

    const { configured, canEditAs } = useClubAuth();
    // The live `club.json` record, for a member looking at a profile they may
    // edit: a bio saved a minute ago is not in the bundle yet (§8.8).
    const { profile, loading: profileLoading, applyLocal } = useMemberProfile(member?.name);

    if (loading) return <LoadingSpinner />;
    if (error || !member) {
        return <ErrorDisplay message={error || "Could not load profile details."} backPath="/about" backButtonLabel="Back to About Page" />;
    }

    // Everything below renders the live record when there is one, so a save
    // shows on the page that asked for it rather than after the next build.
    const shown = profile ?? member;
    const canEdit = configured && canEditAs(shown.name);

    // Constants for UI display, can remain in component
    const MAX_INTERVIEW_ITEMS_BEFORE_SCROLL = 2;
    const needsInterviewExpansion = shown.interview && shown.interview.length > MAX_INTERVIEW_ITEMS_BEFORE_SCROLL;
    const collapsedInterviewMaxHeight = 'max-h-80';
    const hasEnoughControversialFilms = mostControversialFilms.length >= 1;
    const hasStats = currentUserStats && Object.entries(currentUserStats).some(([key, val]) =>
        (val !== null && val !== 0 && (!Array.isArray(val) || val.length > 0))
        || (key === 'totalSelections' && val === 0)
    );
    const MAX_BLURBS_COLLAPSED = 3;
    const needsBlurbsSectionExpansion = reviewBlurbs.length > MAX_BLURBS_COLLAPSED;
    const displayedBlurbs = isBlurbsSectionExpanded ? reviewBlurbs : reviewBlurbs.slice(0, MAX_BLURBS_COLLAPSED);
    const MAX_RATING_DISPLAY = 9;

    return (
        <PageLayout>
            <Button
                onClick={() => navigate(-1)}
                variant="link"
                size="md"
                className="mb-8 group"
            >
                <ChevronLeftIcon className="h-5 w-5 transition-transform group-hover:-translate-x-1" aria-hidden="true" />
                Back
            </Button>

            {/* Content is capped at the un-bled width and centered, so when the
                card bleeds wider on large screens the extra width is banner art
                only — the avatar and bio stay where they were. */}
            <HeroBanner
                films={topRatedFilms}
                className="mb-8"
                contentClassName="mx-auto w-full max-w-[74rem] py-12 sm:p-6 md:p-10 flex flex-col sm:flex-row items-center sm:items-start sm:space-x-10 md:space-x-16"
            >
                <CircularImage
                    src={shown.image}
                    alt={shown.name}
                    size="w-36 h-36 sm:w-40 sm:h-40 md:w-48 md:h-48"
                    className="flex-shrink-0 border-2 border-slate-600 mb-4 !sm:mb-6 sm:mb-0 shadow-lg"
                />
                <div className="text-center sm:text-left flex-grow min-w-0 sm:ml-8 mt-3 sm:mt-2">
                    <h1 className="text-3xl sm:text-4xl text-slate-100 mb-2 break-words font-thin">{shown.name}</h1>
                    <p className="text-lg text-blue-400/90 mb-1">{shown.title}</p>
                    <div className="text-slate-300 leading-relaxed mx-auto sm:mx-0 prose prose-sm prose-invert max-w-none">
                        <Markdown>{shown.bio}</Markdown>
                    </div>
                    {shown.url && (
                        <div className="mt-4">
                            <a className="text-blue-400" href={shown.url}>{shown.url.replace('https://', '')}</a>
                        </div>
                    )}
                </div>
            </HeroBanner>

            {/* The way into editing this profile, for the member it belongs to
                (or an admin). Everyone else sees the page exactly as it was
                before editing existed; signing in is offered in the nav and
                nowhere else. */}
            {canEdit && (
                <ProfileEditor member={shown} profileLoading={profileLoading} onSaved={applyLocal} />
            )}

            {/* Renders nothing when this member has no lists — unless the
                signed-in member is looking at their own profile, where it is
                the way into the list editor. */}
            <ProfileListsSection lists={lists} owner={member.name} />

            {/* Personal watches, sitting alongside the lists at the top of the
                page but out of every club statistic below them — see
                `types/watched.ts`. Renders nothing for a member with an empty
                log, unless it's their own profile. */}
            <ProfileWatchedSection owner={member.name} />

            {shown.interview && shown.interview.length > 0 && (
                <AccentCard accent="blue" className="p-6 md:p-10 mb-8">
                    <h3 className="text-2xl font-bold text-slate-100 mb-4 border-b border-slate-700/60 pb-3"> Interview </h3>
                    <div className={`transition-all duration-500 ease-in-out overflow-hidden ${!isInterviewExpanded && needsInterviewExpansion ? collapsedInterviewMaxHeight : 'max-h-[1500px]'}`}>
                        <div className={`pr-2 -mr-2 ${!isInterviewExpanded && needsInterviewExpansion ? 'overflow-y-auto ' + collapsedInterviewMaxHeight : ''}`}>
                            <div className="divide-y divide-slate-700/60-mt-4">
                                {shown.interview.map((item, index) => <InterviewItem key={index} question={item.question} answer={item.answer} />)}
                            </div>
                        </div>
                    </div>
                    {needsInterviewExpansion && (
                        <div className="mt-4 text-center border-t border-slate-700/60 pt-4">
                            <Button
                                onClick={toggleInterviewExpanded}
                                variant="link"
                                aria-expanded={isInterviewExpanded}
                            >
                                {isInterviewExpanded ? (<> Show Less <ChevronUpIcon className="h-4 w-4" aria-hidden="true" /> </>) : (<> Show Full Interview <ChevronDownIcon className="h-4 w-4" aria-hidden="true" /> </>)}
                            </Button>
                        </div>
                    )}
                </AccentCard>
            )}

            {(hasStats || hasEnoughControversialFilms) && (
                <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 mb-8">
                    <div className={`lg:col-span-2 ${!hasStats ? 'hidden lg:block' : ''}`}>
                        {hasStats ? (
                            <ProfileStatsSection stats={currentUserStats} rankings={rankings} />
                        ) : (
                            <div className="hidden lg:block lg:col-span-2"></div>
                        )}
                    </div>
                    {hasEnoughControversialFilms && (
                        <div className="lg:col-span-1">
                            <AccentCard accent="rose" className="p-6 h-full">
                                <h4 className="text-lg font-semibold text-slate-200 mb-3 pb-2 border-b border-slate-700/60">
                                    Most Divergent Scores
                                </h4>
                                <div className="space-y-3">
                                    {mostControversialFilms.map((film) => (
                                        <ControversialFilmItem key={film.filmId} film={film} />
                                    ))}
                                </div>
                                <p className="text-xs text-slate-500 mt-4 text-center italic">
                                    Films where {member.name} had the largest score difference (magnitude) from the club average.
                                </p>
                            </AccentCard>
                        </div>
                    )}
                     {!hasEnoughControversialFilms && hasStats && (
                        <div className="lg:col-span-1 hidden lg:block"></div>
                    )}
                </div>
            )}

            {reviewBlurbs.length > 0 && (
                <AccentCard accent="emerald" className="p-6 md:p-10 mb-8">
                    <h4 className="text-xl font-bold text-slate-100 mb-6 border-b border-slate-700/60 pb-3">In Their Own Words</h4>
                    <div className="space-y-5">
                        {displayedBlurbs.map((blurbItem) => (
                            <div key={blurbItem.filmId} className="pt-5 border-t border-slate-700/60 first:pt-0 first:border-t-0">
                                <ProfileBlurbItem blurbItem={blurbItem} maxRating={MAX_RATING_DISPLAY} />
                            </div>
                        ))}
                    </div>
                    {needsBlurbsSectionExpansion && (
                        <div className="mt-6 text-center border-t border-slate-700/60 pt-4">
                            <Button
                                onClick={toggleBlurbsSectionExpanded}
                                variant="link"
                                aria-expanded={isBlurbsSectionExpanded}
                            >
                                {isBlurbsSectionExpanded ? (<> Show Fewer Reviews <ChevronUpIcon className="h-4 w-4" /> </>) : (<> Show More Reviews <ChevronDownIcon className="h-4 w-4" /> </>)}
                            </Button>
                        </div>
                    )}
                </AccentCard>
            )}

            {/* Trophy Case Section */}
            {allFilms && member.name && (
                <ProfileTrophyGallery memberName={member.name} films={allFilms} />
            )}

            {topRatedFilms.length > 0 && (
                <div className="mb-12 mt-8">
                    <FilmList
                        films={topRatedFilms}
                        title={`Top ${topRatedFilms.length} Rated Film${topRatedFilms.length !== 1 ? 's' : ''} by ${member.name}`}
                    />
                </div>
            )}

            {selectedFilms.length > 0 ? (
                <div className="mb-12 mt-8">
                    <FilmList
                        films={selectedFilms}
                        title={`Films Selected by ${member.name}`}
                    />
                </div>
            ) : (
                (!currentUserStats || currentUserStats.totalSelections === null || currentUserStats.totalSelections < 0) && (
                    <div className="text-center py-8 text-slate-400 italic mt-8">
                        {member.name} hasn't selected any films yet.
                    </div>
                )
            )}
        </PageLayout>
    );
};

export default ProfilePage;